// Item 22b.5 M3b-i: the pinned log-additive decomposition mode, verified end
// to end against the pinned rjd3 3.9.0 jars. Every embedded value comes
// verbatim (17 significant digits) from validation/evidence/native/
// x11-{bpass,cpass,dpass,selection}-log, captured by
// validation/reference/capture-x11-{bpass,cpass,dpass,selection}.R
// --mode=LogAdditive from the pinned X11BStep/X11CStep/X11DStep/X11Kernel.
// The pinned kernel applies the DoubleSeq.log() (= Math::log, natural log)
// input transform before the steps and the steps then run the plain ADDITIVE
// arithmetic — isMultiplicative() is false under LogAdditive, so ctx.remove
// stays x - y, the mode default stays 0 and none of the makePositivity trend
// guards engage (no repair columns exist in these fixtures). The delivered
// tables are therefore exactly the step-level log-domain tables; the results
// builder's exp of D10..D13 and its LogAdditive bias-correction skip are
// export-stage behaviour and not delivered (the exp bit-qualification of
// Math::exp over the delivered log tables would be M3b export-stage scope).
// The b_pinned/c_pinned/d_pinned subsets are the quarterly inventory with the
// two repair-carrying categories of the multiplicative run appended to the
// additive embedded selection (the monthly inventory is re-verified by the
// tools/verify_x11_*pass sweeps over the full fixture); the selection subset
// is the complete 15-case pinned kernel inventory in log-additive mode. In
// the log domain the constant-series controls degenerate like the additive
// fixture (NaN I/C ratio at B7 -> unsupported), in contrast to the
// multiplicative run where the constant-msr contrast is decided. The
// pseudo-additive mode is a delivered mode since item 22b.5 M3b-ii (qualified
// in tests/test_x11_pseudo_additive.cpp), so the only pinned failure left here
// is the non-positive log-additive input with the pinned kernel message (the
// pinned positivity gate is
// mode == Multiplicative || mode == LogAdditive with one constant message).
// Contract: docs/contracts/x11-log-additive-contract.md.
